# %% [markdown]
# # specs_novel — G0.1-R2: re-embed the corpus with the fixed `dreams_peaks` (Colab, GPU)
#
# **Generated by `build/mk_novel_p0.py` — do not hand-edit.** Pre-registered in
# `specs_novel/gate_report.md` → *G0.1-R2*. Precondition for P3.
#
# G0.1-R failed because `np.argsort` let the platform choose which intensity-tied peaks survive the
# top-100 cut. `dreams_peaks` now uses `np.lexsort` (ties go to the higher m/z). This notebook:
#
# 1. rebuilds every corpus row's peaks with the fixed code and flags rows with a **tie at the cut**;
# 2. picks **`parity_lx`** — 200 rows, 150 of them tie rows spread over libraries — and saves their
#    peaks to `_novel/lx/parity_lx.npz` **before** embedding, so the Colab CPU leg
#    (`casmi_novel_lx_cpu_colab.ipynb`) can start in parallel;
# 3. embeds all 1,323,878 rows into the **new** folder `_novel/emb_dbec3a0_lx/` (resumable; the old
#    caches are only read);
# 4. records new vs `emb_dbec3a0` (the accepted risk, measured) and packages the Kaggle dataset
#    **casmi26-novel-lx** for the Kaggle leg (`casmi_novel_lx_kaggle.ipynb`).
#
# G0.1-R2 passes when this notebook's checks pass **and** the CPU and Kaggle legs rebuild
# byte-identical peaks, **and** Kaggle's vectors reach cosine ≥ 0.999 with the new cache on every row.
#
# Runtime: **GPU with High-RAM** (A100 ≈ 35 min; T4 ≈ 2.5 h).

# %%
import os, sys, json, time, shutil, hashlib
from pathlib import Path
import numpy as np
import pandas as pd
import pyarrow.parquet as pq
import torch

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path("/content/drive/MyDrive/casmi_2026")
TRAIN = ROOT / "enveda-CASMI26-molecule-id-mass-spectra" / "train.parquet"
DOUT = ROOT / "_dreams_out"                     # corpus_meta.parquet (read only)
GATE = ROOT / "_novel" / "p0"                   # corpus_ce.parquet, dreams_embed.pt (read only)
PREV = ROOT / "_novel" / "emb_dbec3a0"          # the provisional cache (unstable tie-break; read only)
OUT = ROOT / "_novel" / "emb_dbec3a0_lx"        # the new cache
LX = ROOT / "_novel" / "lx"                     # parity_lx.npz, lx_gpu.json, kaggle_upload/
UPLOAD = LX / "kaggle_upload"                   # becomes the Kaggle dataset casmi26-novel-lx
WORK = Path("/content/novel_lx")
SRC = WORK / "src"
for p in (OUT, LX, WORK, SRC):
    p.mkdir(parents=True, exist_ok=True)

DREAMS_COMMIT = "dbec3a0b514a99e5056cfccde4559fda8cfe8129"
DREAMS_INFER_SHA1 = "57ce1bc15414d82ff07989824fd31926ec30eb6b"   # lexsort dreams_peaks (gate_report G0.1-R2)
DREAMS_EMBED_SHA1 = "a28488b277162f42d6361e339ffa54217a9d7381"
CHUNK = 200_000                                 # rows per emb_*.npy, as in both earlier caches
DIM = 1024
BATCH = 256
COS_MIN = 0.999                                 # G0.1-R2: Kaggle vectors vs new cache, every parity row
N_TIE = 150                                     # parity_lx: at least half tie rows (pre-registered)
N_OTHER = 50
SEED = 20260929
KAGGLE_USER = "YOUR_KAGGLE_USERNAME"            # only used in the dataset-metadata.json that is written

assert OUT != PREV and not any(OUT.glob("emb_*.npy.tmp"))
RESULT = {"started": time.strftime("%Y-%m-%d %H:%M"), "dreams_commit": DREAMS_COMMIT,
          "dreams_embed_sha1": DREAMS_EMBED_SHA1, "out": str(OUT), "batch_size": BATCH}

def save_result():
    (LX / "lx_gpu.json").write_text(json.dumps(RESULT, indent=1, default=str))

assert torch.cuda.is_available(), "switch the runtime to a GPU"
torch.backends.cuda.matmul.allow_tf32 = False   # plain float32, as on the Kaggle leg
torch.backends.cudnn.allow_tf32 = False
DEV = "cuda:0"
RESULT["gpu"] = torch.cuda.get_device_name(0)
RESULT["torch"] = torch.__version__
for name, p in [("train.parquet", TRAIN), ("corpus_meta.parquet", DOUT / "corpus_meta.parquet"),
                ("corpus_ce.parquet", GATE / "corpus_ce.parquet"), ("dreams_embed.pt", GATE / "dreams_embed.pt"),
                ("emb_dbec3a0/", PREV)]:
    print(f"{'ok ' if p.exists() else '!! '} {name:20} {p}")
    assert p.exists(), p
print(RESULT)

# %% [markdown]
# ## Sources (embedded verbatim; `dreams_infer` checked against the pre-registered SHA1)

# %%
DREAMS_INFER_SRC = None  # @@DREAMS_INFER@@
NOVEL_LX_SRC = None  # @@NOVEL_LX@@

got = hashlib.sha1(DREAMS_INFER_SRC.encode("utf-8")).hexdigest()
assert got == DREAMS_INFER_SHA1, f"dreams_infer.py {got} != pre-registered {DREAMS_INFER_SHA1}"
for fname, text in [("dreams_infer.py", DREAMS_INFER_SRC), ("novel_lx.py", NOVEL_LX_SRC)]:
    (SRC / fname).write_text(text, encoding="utf-8")
sys.path.insert(0, str(SRC))
import dreams_infer as di
import novel_lx as lx
MODEL, MMETA = di.load_dreams(GATE / "dreams_embed.pt", device=DEV, expect_sha1=DREAMS_EMBED_SHA1)
RESULT["src_sha1"] = {"dreams_infer.py": got,
                      "novel_lx.py": hashlib.sha1(NOVEL_LX_SRC.encode("utf-8")).hexdigest()}
RESULT["host"] = lx.host_info()
print(f"loaded dreams_embed.pt on {DEV}: {MMETA}\nhost: {RESULT['host']}")

# %% [markdown]
# ## Row order and resume state

# %%
t0 = time.time()
META = pd.read_parquet(DOUT / "corpus_meta.parquet", columns=["ingest_lib", "inchikey14", "adduct",
                                                                "precursor_mz", "oob_mass"])
N = len(META)
TROW = pq.read_table(GATE / "corpus_ce.parquet", columns=["row", "train_row"]).to_pandas()
assert len(TROW) == N and (TROW.row.to_numpy() == np.arange(N)).all()
TROW = TROW.train_row.to_numpy(np.int64)
ids = pq.read_table(TRAIN, columns=["inchikey14", "adduct", "precursor_mz"]).to_pandas().iloc[TROW]
order_bad = {c: int((ids[c].astype(str).to_numpy() != META[c].astype(str).to_numpy()).sum())
             for c in ("inchikey14", "adduct")}
order_bad["precursor_mz"] = int((ids.precursor_mz.to_numpy(np.float64) != META.precursor_mz.to_numpy(np.float64)).sum())
assert not any(order_bad.values()), f"corpus_ce train_row does not line up with corpus_meta: {order_bad}"
PREC = META.precursor_mz.to_numpy(np.float64)
del ids

def chunk_bounds(n, chunk):
    return [(lo, min(lo + chunk, n)) for lo in range(0, n, chunk)]

def chunk_done(path, rows):
    if not path.exists():
        return False
    try:
        a = np.load(path, mmap_mode="r")
    except Exception:
        return False
    return a.shape == (rows, DIM) and a.dtype == np.float32

BOUNDS = chunk_bounds(N, CHUNK)
TODO = [i for i, (lo, hi) in enumerate(BOUNDS) if not chunk_done(OUT / f"emb_{i:04d}.npy", hi - lo)]
RESULT.update(rows=N, chunks=len(BOUNDS), order_mismatches=order_bad)
save_result()
print(f"{N:,} rows in {len(BOUNDS)} chunks; to embed: {TODO} ({time.time() - t0:.0f}s)")

# %% [markdown]
# ## Peaks and the tie-at-the-cut flag for every corpus row
#
# One streaming pass over `train.parquet` with the fixed `di.dreams_peaks`; `lx.cut_tie` uses the
# same filters and flags rows whose top-100 cut falls inside an intensity tie.

# %%
t0 = time.time()
assert (di.INT_FLOOR, di.N_PEAKS, di.DROP_ABOVE_PRECURSOR) == (0.002, 100, 2.0)
PLS = [None] * N
TIE = np.zeros(N, bool)

def on_row(j, mz, it):
    PLS[j] = di.dreams_peaks(mz, it, PREC[j])
    if len(mz) > di.N_PEAKS:
        TIE[j] = lx.cut_tie(mz, it, PREC[j], di.INT_FLOOR, di.N_PEAKS, di.DROP_ABOVE_PRECURSOR)

lx.stream_rows(TRAIN, TROW, on_row)
lost = [j for j, p in enumerate(PLS) if p is None]
assert not lost, f"{len(lost)} corpus rows have no usable peaks (first: {lost[:5]})"
NPK = np.array([p.shape[1] for p in PLS], np.int16)
RESULT.update(t_peaks_s=round(time.time() - t0), tie_rows=int(TIE.sum()), tie_share=float(TIE.mean()))
save_result()
print(f"peaks for {N:,} rows ({time.time() - t0:.0f}s); median kept {np.median(NPK):.0f}; "
      f"tie at the cut: {TIE.sum():,} rows ({100 * TIE.mean():.2f} %)")

# %% [markdown]
# ## `parity_lx` — pick and save the peaks now (the CPU leg can start after this cell)

# %%
LIB = META.ingest_lib.astype(str).to_numpy()
PROW = lx.pick_parity(TIE, LIB, N_TIE, N_OTHER, SEED)
PPL = [PLS[r] for r in PROW]
PMZ, PIT, POFF = lx.pack_peaks(PPL)
DIGEST = lx.peaks_digest(PPL, PREC[PROW])
PARITY = dict(row=PROW, train_row=TROW[PROW], prec=PREC[PROW], mz=PMZ, it=PIT, off=POFF, tie=TIE[PROW],
              lib=LIB[PROW].astype("U"), inchikey14=META.inchikey14.astype(str).to_numpy()[PROW].astype("U"),
              adduct=META.adduct.astype(str).to_numpy()[PROW].astype("U"))   # fixed-width: np.load needs no pickle

def save_parity(extra=None):
    tmp = WORK / "parity_lx.npz"
    np.savez(tmp, **PARITY, **(extra or {}))
    shutil.copyfile(tmp, LX / "parity_lx.npz.tmp")
    os.replace(LX / "parity_lx.npz.tmp", LX / "parity_lx.npz")

save_parity()
RESULT["parity_lx"] = dict(n=len(PROW), n_tie=int(TIE[PROW].sum()), peaks_digest=DIGEST,
                           by_lib=pd.Series(LIB[PROW][TIE[PROW]]).value_counts().to_dict())
save_result()
assert TIE[PROW].sum() * 2 >= len(PROW), "fewer than half of parity_lx are tie rows"
print(f"parity_lx: {len(PROW)} rows, {TIE[PROW].sum()} with a tie at the cut; digest {DIGEST}")
print(f"tie rows by library: {RESULT['parity_lx']['by_lib']}")
print("-> the Colab CPU leg (casmi_novel_lx_cpu_colab.ipynb) can be started now")

# %% [markdown]
# ## Embed, chunk by chunk (resumable)

# %%
di.dreams_embed(MODEL, PLS[:8], PREC[:8])                  # warm-up
t_all = time.time()
for i in TODO:
    lo, hi = BOUNDS[i]
    t0 = time.time()
    E = di.dreams_embed(MODEL, PLS[lo:hi], PREC[lo:hi], batch_size=BATCH)
    torch.cuda.synchronize(DEV)
    assert E.shape == (hi - lo, DIM) and E.dtype == np.float32 and np.isfinite(E).all(), (i, E.shape)
    local = WORK / f"emb_{i:04d}.npy"
    np.save(local, E)
    tmp = OUT / f"emb_{i:04d}.npy.tmp"
    shutil.copyfile(local, tmp)
    os.replace(tmp, OUT / f"emb_{i:04d}.npy")
    local.unlink()
    dt = time.time() - t0
    print(f"chunk {i:04d} rows {lo:,}-{hi:,}: {dt:.0f}s ({1000 * dt / (hi - lo):.2f} ms/spectrum)", flush=True)
RESULT["t_embed_s"] = round(time.time() - t_all)
RESULT["embedded_chunks_this_session"] = TODO
save_result()

# %% [markdown]
# ## GPU-host checks
#
# Every row finite and 1024-d. The parity rows' cache vectors are stored in `parity_lx.npz` for the
# Kaggle leg; a fresh embed of the same peaks at the Kaggle batch size (64) is recorded as a
# same-host sanity check.

# %%
NEW = [np.load(OUT / f"emb_{i:04d}.npy", mmap_mode="r") for i in range(len(BOUNDS))]
assert sum(a.shape[0] for a in NEW) == N and all(a.shape[1] == DIM and a.dtype == np.float32 for a in NEW)
finite = all(bool(np.isfinite(np.asarray(a)).all()) for a in NEW)

def rows_of(chunks, rows):
    return np.stack([np.asarray(chunks[r // CHUNK][r % CHUNK]) for r in rows]).astype(np.float32)

PEMB = rows_of(NEW, PROW)
save_parity({"emb": PEMB})
fresh = di.dreams_embed(MODEL, PPL, PREC[PROW], batch_size=64)
cos_fresh = lx.rowcos(PEMB, fresh)
GPU_OK = bool(finite and not any(order_bad.values()) and cos_fresh.min() >= COS_MIN)
RESULT["gpu_leg"] = dict(rows=N, finite=finite, order_ok=not any(order_bad.values()),
                         cos_cache_vs_fresh_b64_min=float(cos_fresh.min()), passed=GPU_OK)
save_result()
print(f"all finite: {finite}; cache vs fresh (batch 64) min {cos_fresh.min():.9f}; GPU leg {'OK' if GPU_OK else 'FAIL'}")

# %% [markdown]
# ## New vs `emb_dbec3a0` over the whole corpus (recorded, not gating)
#
# This measures the risk accepted when G0 was closed by decision: how far the provisional cache is
# from the fixed code. Tie rows are split out.

# %%
t0 = time.time()
PRV = [np.load(PREV / f"emb_{i:04d}.npy", mmap_mode="r") for i in range(len(BOUNDS))]
COS = np.empty(N, np.float64)
for i, (lo, hi) in enumerate(BOUNDS):
    for a in range(0, hi - lo, 50_000):
        b = min(a + 50_000, hi - lo)
        COS[lo + a:lo + b] = lx.rowcos(np.asarray(NEW[i][a:b]), np.asarray(PRV[i][a:b]))
np.save(OUT / "cos_lx_vs_dbec3a0.npy", COS.astype(np.float32))

QS = [0.0, 0.001, 0.01, 0.1, 0.5]

def summarise(cos, groups):
    """Per group: n, min, median and the share below 0.999, worst groups first."""
    df = pd.DataFrame({"g": groups, "cos": cos})
    out = df.groupby("g").cos.agg(n="size", min="min", median="median",
                                  below_0999=lambda s: float((s < 0.999).mean()))
    return out.sort_values("min").reset_index()

overall = {f"q{q:g}": float(np.quantile(COS, q)) for q in QS}
overall.update(below_0999=float((COS < 0.999).mean()), below_0995=float((COS < 0.995).mean()),
               below_099=float((COS < 0.99).mean()), non_tie_min=float(COS[~TIE].min()) if (~TIE).any() else None)
BY = {"tie_at_cut": TIE.astype(int), "ingest_lib": LIB, "adduct": META.adduct.astype(str).to_numpy(),
      "oob_mass": META.oob_mass.to_numpy(), "npk_bin": np.digitize(NPK, [10, 40])}
by = {k: summarise(COS, v).to_dict("records") for k, v in BY.items()}
RESULT["lx_vs_dbec3a0"] = dict(overall=overall, by=by, seconds=round(time.time() - t0))
save_result()
print(json.dumps(overall, indent=1))
for k in BY:
    print(f"\nby {k}:\n{summarise(COS, BY[k]).head(12).to_string(index=False)}")

# %% [markdown]
# ## Manifest and the Kaggle dataset `casmi26-novel-lx`

# %%
MANIFEST = dict(
    rows=N, chunks=len(BOUNDS), chunk_rows=CHUNK, dim=DIM, dtype="float32",
    order="row i = corpus_meta.parquet row i (P0.2 replay; train.parquet index in corpus_ce.parquet train_row)",
    dreams_commit=DREAMS_COMMIT, dreams_embed_sha1=DREAMS_EMBED_SHA1, dreams_infer_sha1=DREAMS_INFER_SHA1,
    gpu=RESULT["gpu"], torch=RESULT["torch"], batch_size=BATCH, tf32=False, host=RESULT["host"],
    chunk_sha1={f"emb_{i:04d}.npy": di.sha1(OUT / f"emb_{i:04d}.npy") for i in range(len(BOUNDS))},
    parity_peaks_digest=DIGEST, gpu_leg=RESULT["gpu_leg"], built=time.strftime("%Y-%m-%d %H:%M"))
(OUT / "manifest.json").write_text(json.dumps(MANIFEST, indent=1))

if UPLOAD.exists():
    shutil.rmtree(UPLOAD)
UPLOAD.mkdir(parents=True)
for f in ("dreams_embed.pt",):
    shutil.copy2(GATE / f, UPLOAD / f)
shutil.copy2(LX / "parity_lx.npz", UPLOAD / "parity_lx.npz")
KMAN = dict(dreams_embed_sha1=DREAMS_EMBED_SHA1, dreams_infer_sha1=DREAMS_INFER_SHA1,
            novel_lx_sha1=RESULT["src_sha1"]["novel_lx.py"], parity_sha1=di.sha1(UPLOAD / "parity_lx.npz"),
            parity_peaks_digest=DIGEST, cos_min=COS_MIN, gpu_host=RESULT["host"], gpu=RESULT["gpu"])
(UPLOAD / "manifest_lx.json").write_text(json.dumps(KMAN, indent=1))
(UPLOAD / "dataset-metadata.json").write_text(json.dumps(
    {"title": "casmi26-novel-lx", "id": f"{KAGGLE_USER}/casmi26-novel-lx",
     "licenses": [{"name": "other"}]}, indent=1))
size = sum(p.stat().st_size for p in UPLOAD.rglob("*") if p.is_file())
RESULT.update(upload=dict(path=str(UPLOAD), mb=size / 1e6, manifest=KMAN), finished=time.strftime("%Y-%m-%d %H:%M"))
save_result()

print("=" * 88)
print(f"G0.1-R2 GPU leg: {'OK' if GPU_OK else 'FAIL'}  (rows {N:,}, finite {finite}, order mismatches {order_bad})")
print(f"parity_lx: {len(PROW)} rows, {TIE[PROW].sum()} tie; peaks digest {DIGEST}")
print(f"lx vs dbec3a0: min {overall['q0']:.6f}, p0.1% {overall['q0.001']:.6f}; share < 0.999 {overall['below_0999']:.4f}; "
      f"non-tie min {overall['non_tie_min']}")
print("=" * 88)
print(f"new cache: {OUT}\nKaggle dataset folder: {UPLOAD} ({size / 1e6:.0f} MB) -> upload as casmi26-novel-lx")
print(f"report: {LX / 'lx_gpu.json'}")
